<?php namespace App\Http\Controllers; use App\Http\Requests\AvailabilityRequest; use App\Models\{Vet,VetAvailability}; use Illuminate\Http\Request; class AvailabilityController extends Controller { public function index(Vet $vet){return $vet->availabilities()->where('is_active',true)->orderBy('day_of_week')->orderBy('start_time')->get();} public function store(AvailabilityRequest $r){$vet=Vet::where('user_id',$r->user()->id)->firstOrFail();return $vet->availabilities()->create($r->validated());} public function update(AvailabilityRequest $r,VetAvailability $availability){abort_unless($availability->vet->user_id===$r->user()->id,403);$availability->update($r->validated());return $availability;} public function destroy(Request $r,VetAvailability $availability){abort_unless($availability->vet->user_id===$r->user()->id,403);$availability->delete();return response()->noContent();} }